        args is CreateArguments c&&c.Entities.Any(e=>e is ConstructionCurve443 or AssociativeHatchSpec or MLeaderBlockSpec442 or ModelLoftSpec or ModelSweepSpec or ModelExtrusionSpec)||
        args is StructureWriteArguments s&&s.Operations.Any(e=>e is DefineBlockEdit { Entities: var members } && members.Any(m=>m is HatchSpec or BlockReferenceSpec391) || e is InsertBlockEdit or ExternalReferenceEdit385 or InsertBlockArray384 or SetBlockArray384 or RenameBlockDefinition349 or SetBlockDefinitionGeometry388 or SetBlockDefinitionText391 or SetBlockDefinitionMembers392 or NativeStyleLifecycle352 or TableStyleEdit337 or MLeaderStyleEdit337 or CreateViewportEdit or SetViewportViewEdit or SetViewportClipping358 or ViewportLifecycleEdit or SetDrawingViewPropertiesEdit or DeleteDrawingViewsEdit or StructureLifecycleEdit{Operation:"delete_layout" or "set_current_dimension_style"})||
        args is ModifyArguments m&&m.Operations.Any(e=>e is CreateAssociativeRectangularArray431 or SetAssociativeRectangularArray431 or MLeaderTopologyEdit431 or WipeoutBoundaryEdit431 or NativeExplode386 or SolidImprintEditSpec393 or SolidBooleanEditSpec or SolidFaceEditSpec or ModelManufacturingEdit or SliceSolidSpec or SeparateSolidSpec or SolidFinishingEditSpec or SolidOffsetEdit353 or SolidDrillEditSpec or ModelFeatureExtrusionSpec or ModelFeatureRevolutionSpec or ModelPatternSpec or ModelPatternElementSpec or ModelShellSpec or ModelShellThicknessSpec or ModelFeatureSuppressionSpec or ModelEdgeFeatureSpec or ModelSketchEdit or ModelPlacementEdit or ModelRevolutionEdit or SketchConstraintsEdit or ModelParameterNameEdit or ModelUserVariableEdit)||
        args is ModifyArguments tables&&tables.Operations.Any(e=>e is ReplaceTableTextSpec or ResizeTableSpec or TableEditingSpec or TableContentsEditing364 or TableValueEditingSpec or TableCellLayoutEdit340 or TableGridLayoutEdit341 or DimensionDisplayEdit341 or DimensionDefinitionEdit341 or NativeOffsetCurveSpec341 or SetMTextFormatSpec or SetTextFormat442 or SetMLeaderInstance442 or ReplaceMLeaderTextSpec or SetHatchPropertiesSpec or RegionBooleanEditSpec or Mirror2dSpec or ModelProfileCreate340 or ModelProfileExtrude340 or ModelSketchCreate362 or ModelSketchProfileCreate362 or ModelProfileSweep362 or ModelProfileRevolution411 or ModelProfileLoft446)||
        args is ModifyArguments nativeContours&&nativeContours.Operations.Any(e=>e is NativeContourFinishingSpec342 or NativeCornerCurveSpec343 or TableFormulaEditingSpec343 or TableFormulaRangeSpec350)||
        args is StructureWriteArguments nestedAttributes&&nestedAttributes.Operations.Any(e=>e is DrawingGroupEdit431 or SetAttributeEdit{OwnerDefinitionHandle:not null})||
        args is ModelParameterArguments p&&p.UsesExpressionPlan;
    public static bool UnknownFailure(bool started,bool commitAttempted,bool cleanupFailed,bool rollbackNotGuaranteed)=>
        commitAttempted||cleanupFailed||started&&rollbackNotGuaranteed;
}
